// Compare what you sent against what came back, per thread. No API calls here.
const cfg = $('Set config: window, tone and recipients').first().json;
const sent = $('Fetch the messages you sent').all().map((it) => it.json);
const received = $input.all().map((it) => it.json);

const header = (m, name) => {
  const hs = (m.payload && m.payload.headers) || m.headers || [];
  const hit = Array.isArray(hs) ? hs.find((h) => String(h.name || '').toLowerCase() === name) : null;
  return hit ? String(hit.value || '') : '';
};
const stamp = (m) => {
  const raw = m.internalDate || m.internalDateMs || '';
  const n = Number(raw);
  if (Number.isFinite(n) && n > 0) return n;
  const d = Date.parse(header(m, 'date') || m.date || m.Date || '');
  return Number.isFinite(d) ? d : 0;
};
const addressOf = (v) => {
  const s = String(v || '');
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim().toLowerCase();
};
const clean = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/g, ' ').replace(/\s+/g, ' ').trim();

const blocked = String(cfg.excludeTerms || '')
  .split(',').map((t) => t.trim().toLowerCase()).filter(Boolean);

// Latest outbound message per thread.
const lastSent = new Map();
for (const m of sent) {
  const thread = m.threadId || m.id;
  if (!thread) continue;
  const ts = stamp(m);
  const prev = lastSent.get(thread);
  if (prev && prev.ts >= ts) continue;
  lastSent.set(thread, {
    ts,
    to: addressOf(header(m, 'to') || m.to || m.To),
    subject: header(m, 'subject') || m.subject || m.Subject || '(no subject)',
    snippet: clean(m.snippet || m.text || m.textPlain || '').slice(0, 400),
  });
}

// Latest inbound message per thread.
const lastReply = new Map();
for (const m of received) {
  const thread = m.threadId || m.id;
  if (!thread) continue;
  const ts = stamp(m);
  if (!lastReply.has(thread) || lastReply.get(thread) < ts) lastReply.set(thread, ts);
}

const now = Date.now();
const out = [];
for (const [thread, s] of lastSent.entries()) {
  if (!s.to) continue;
  if (blocked.some((t) => s.to.includes(t))) continue;
  const replied = lastReply.get(thread) || 0;
  if (replied > s.ts) continue; // they answered after your last message
  const daysSilent = Math.floor((now - s.ts) / 86400000);
  out.push({ json: {
    threadId: thread,
    to: s.to,
    subject: s.subject,
    snippet: s.snippet,
    daysSilent,
    lastSentAt: new Date(s.ts).toISOString().slice(0, 10),
  } });
}

out.sort((a, b) => b.json.daysSilent - a.json.daysSilent);
return out.slice(0, Number(cfg.maxThreads) || 25);

const cfg = $('Set config: window, tone and recipients').first().json;
const threads = $input.all().map((it) => it.json);
const schema = { type: 'object', additionalProperties: false, required: ['followups'], properties: {
  followups: { type: 'array', items: { type: 'object', additionalProperties: false,
    required: ['i', 'priority', 'reason', 'body'], properties: {
      i: { type: 'integer' },
      priority: { type: 'string', enum: ['high', 'medium', 'low'] },
      reason: { type: 'string' },
      body: { type: 'string' } } } } } };

const system = 'You write short follow-up emails for messages that never got a reply. Tone: ' + cfg.tone +
  '. Rules: never guess facts that are not in the original message, never apologise for following up, ' +
  'never use the phrase "just checking in", keep each body under 70 words, make the ask concrete, ' +
  'and sign off as ' + cfg.yourName + '. Set priority from how much the thread looks like it was going somewhere, ' +
  'not from how old it is. Reason is one short line explaining the priority, for the sender only. ' +
  'Do not use em dashes.';

const user = 'UNANSWERED THREADS (reference each by index i):\n' +
  threads.map((t, i) => '[' + i + '] To: ' + t.to + ' | Subject: ' + t.subject +
    ' | Silent for ' + t.daysSilent + ' days since ' + t.lastSentAt + '\nWhat you last sent: ' + t.snippet).join('\n\n');

return [{ json: { body: {
  model: cfg.model, max_tokens: 3000, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: window, tone and recipients').first().json;
const threads = $('Keep threads past your follow-up window').all().map((it) => it.json);
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{"followups":[]}';
let followups = [];
try { followups = (JSON.parse(text).followups) || []; } catch (e) {}

const rank = { high: 0, medium: 1, low: 2 };
const rows = followups
  .map((f) => ({ f, t: threads[f.i] }))
  .filter((r) => r.t && r.f.body)
  .sort((a, b) => (rank[a.f.priority] ?? 3) - (rank[b.f.priority] ?? 3) || b.t.daysSilent - a.t.daysSilent);

const pad = (s, n) => String(s).slice(0, n).padEnd(n);
const table = rows.map((r) =>
  pad(r.f.priority.toUpperCase(), 7) + pad(String(r.t.daysSilent) + 'd', 5) + pad(r.t.to, 30) + r.t.subject
).join('\n');

const digest = rows.length
  ? rows.length + ' thread' + (rows.length === 1 ? '' : 's') + ' went quiet. A draft reply is waiting in Gmail for each one.\n\n' +
    pad('PRIORITY', 7) + pad('AGE', 5) + pad('WHO', 30) + 'SUBJECT\n' + table + '\n\n' +
    rows.map((r) => 'To: ' + r.t.to + '\nRe: ' + r.t.subject + '\nWhy: ' + r.f.reason + '\n\n' + r.f.body).join('\n\n----\n\n')
  : 'No unanswered threads in your window. Nothing to chase.';

if (!rows.length) return [{ json: { digest, digestTo: cfg.digestTo, empty: true } }];

return rows.map((r) => ({ json: {
  threadId: r.t.threadId,
  to: r.t.to,
  subject: r.t.subject.toLowerCase().startsWith('re:') ? r.t.subject : 'Re: ' + r.t.subject,
  body: r.f.body,
  priority: r.f.priority,
  reason: r.f.reason,
  daysSilent: r.t.daysSilent,
  digest,
  digestTo: cfg.digestTo,
  empty: false,
} }));
